export const AuditLogActorSchema = type({
  'type?': type("'session' | 'api_key'").describe(
    'The type of actor. Is either `session` or `api_key`.',
  ),
  'session?': AuditLogActorSessionSchema,
  'api_key?': AuditLogActorApiKeySchema,
})
  .describe('The actor who performed the audit logged action.')
  .configure({ ref: 'AuditLogActor' })

export type AuditLogActor = typeof AuditLogActorSchema.infer

export const AwsExternalStorageProviderResponseSchema = type({
  type: "'aws'",
  account_id: 'string',
  region: 'string',
  bucket: 'string',
  role_arn: 'string',
  external_id: 'string',
}).configure({ ref: 'AwsExternalStorageProviderResponse' })

export type AwsExternalStorageProviderResponse =
  typeof AwsExternalStorageProviderResponseSchema.infer

export const AzureExternalStorageProviderResponseSchema = type({
  type: "'azure'",
  tenant_id: 'string',
  subscription_id: 'string',
  resource_group: 'string',
  account_name: 'string',
  container: 'string',
  region: 'string',
}).configure({ ref: 'AzureExternalStorageProviderResponse' })

export type AzureExternalStorageProviderResponse =
  typeof AzureExternalStorageProviderResponseSchema.infer

export const GcpExternalStorageProviderResponseSchema = type({
  type: "'gcp'",
  bucket: 'string',
  workload_identity_project_number: 'string',
  workload_identity_pool_id: 'string',
  workload_identity_provider_id: 'string',
  region: 'string',
  audience: 'string',
}).configure({ ref: 'GcpExternalStorageProviderResponse' })

export type GcpExternalStorageProviderResponse =
  typeof GcpExternalStorageProviderResponseSchema.infer

export const OciExternalStorageProviderResponseSchema = type({
  type: "'oci'",
  tenancy_ocid: 'string',
  region: 'string',
  bucket: 'string',
}).configure({ ref: 'OciExternalStorageProviderResponse' })

export type OciExternalStorageProviderResponse =
  typeof OciExternalStorageProviderResponseSchema.infer

export const ProviderSchema = type(
  type(
    type(
      type(AwsExternalStorageProviderResponseSchema).and({
        type: "'AwsExternalStorageProviderResponse'",
      }),
    ).or(
      type(AzureExternalStorageProviderResponseSchema).and({
        type: "'AzureExternalStorageProviderResponse'",
      }),
    ),
  ).or(
    type(GcpExternalStorageProviderResponseSchema).and({
      type: "'GcpExternalStorageProviderResponse'",
    }),
  ),
)
  .or(
    type(OciExternalStorageProviderResponseSchema).and({
      type: "'OciExternalStorageProviderResponse'",
    }),
  )
  .configure({ ref: 'provider' })

export type Provider = typeof ProviderSchema.infer

