export const ComparisonFilterSchema = type({
  type: type("'eq' | 'ne' | 'gt' | 'gte' | 'lt' | 'lte' | 'in' | 'nin'").describe(
    'Specifies the comparison operator: `eq`, `ne`, `gt`, `gte`, `lt`, `lte`, `in`, `nin`.\n- `eq`: equals\n- `ne`: not equal\n- `gt`: greater than\n- `gte`: greater than or equal\n- `lt`: less than\n- `lte`: less than or equal\n- `in`: in\n- `nin`: not in\n',
  ),
  key: type('string').describe('The key to compare against the value.'),
  value: type(type(type('string').or('number')).or('boolean'))
    .or(type('string | number').array())
    .describe(
      'The value to compare against the attribute key; supports string, number, or boolean types.',
    ),
  '+': 'reject',
})
  .describe(
    'A filter used to compare a specified attribute key to a given value using a defined comparison operation.\n',
  )
  .configure({ ref: 'ComparisonFilter' })

export type ComparisonFilter = typeof ComparisonFilterSchema.infer

export const CompleteUploadRequestSchema = type({
  part_ids: type('string[]').describe('The ordered list of Part IDs.\n'),
  'md5?': type('string').describe(
    'The optional md5 checksum for the file contents to verify if the bytes uploaded matches what you expect.\n',
  ),
  '+': 'reject',
}).configure({ ref: 'CompleteUploadRequest' })

export type CompleteUploadRequest = typeof CompleteUploadRequestSchema.infer

export const CompoundFilterSchema = scope({
  ComparisonFilterSchema: ComparisonFilterSchema,
  CompoundFilterSchema: [
    {
      type: ["'and' | 'or'", '@', 'Type of operation: `and` or `or`.'],
      filters: [
        [
          [
            ['ComparisonFilterSchema', '&', { type: "'ComparisonFilter'" }],
            '|',
            ['CompoundFilterSchema', '&', { type: "'CompoundFilter'" }],
          ],
          '[]',
        ],
        '@',
        'Array of filters to combine. Items can be `ComparisonFilter` or `CompoundFilter`.',
      ],
      '+': 'reject',
    },
    '@',
    'Combine multiple filters using `and` or `or`.',
  ],
})
  .export()
  .CompoundFilterSchema.configure({ ref: 'CompoundFilter' })

export type CompoundFilter = typeof CompoundFilterSchema.infer

