export const ImageGenToolSchema = type({
  type: type("'image_generation'").describe(
    'The type of the image generation tool. Always `image_generation`.\n',
  ),
  'model?': type('string').or(
    type(
      "'gpt-image-1' | 'gpt-image-1-mini' | 'gpt-image-2' | 'gpt-image-2-2026-04-21' | 'gpt-image-2.5-sunburst' | 'gpt-image-2.5-sunburst-2026-09-08' | 'gpt-image-2.5-flare' | 'gpt-image-2.5-flare-2026-09-08' | 'gpt-image-2.6-sunburst' | 'gpt-image-2.6-flare' | 'gpt-image-1.5' | 'chatgpt-image-latest'",
    ).describe(
      'The image generation model to use. One of `gpt-image-1-mini`,\n`gpt-image-1.5`, `gpt-image-2`,\n`gpt-image-2-2026-04-21`, `gpt-image-2.5-sunburst`,\n`gpt-image-2.5-sunburst-2026-09-08`, `gpt-image-2.5-flare`,\n`gpt-image-2.5-flare-2026-09-08`, `gpt-image-2.6-sunburst`,\n`gpt-image-2.6-flare`, or `chatgpt-image-latest`. Default:\n`gpt-image-2.6-sunburst`.\n\n`gpt-image-1` was shut down on October 23, 2026. Use\n`gpt-image-2.5-sunburst` or `gpt-image-2.5-flare` instead.\n',
    ),
  ),
  'complexity?': type("'low' | 'medium' | 'high'").describe(
    "Computation spent planning the image, independently of rendering quality.\nOverrides the outer response's `reasoning.effort` for image generation.\nWhen omitted, inherits a supported outer reasoning effort or uses the\nimage model's configured default.\nFor SVG output, controls the reference image, not the SVG author's\nreasoning.\n",
  ),
  'quality?': type("'low' | 'medium' | 'high' | 'xhigh' | 'max' | 'auto'").describe(
    'The quality of the generated image. The GPT image models support `low`,\n`medium`, and `high`. `gpt-image-2.5-sunburst` and `gpt-image-2.5-flare`,\nincluding their `2026-09-08` snapshots, also support `xhigh` and `max`.\nDefault: `auto`.\n',
  ),
  'size?': type("string | '1024x1024' | '1024x1536' | '1536x1024' | 'auto'").describe(
    "The size of the generated images. For `gpt-image-2`, `gpt-image-2-2026-04-21`, `gpt-image-2.5-sunburst`, `gpt-image-2.5-sunburst-2026-09-08`, `gpt-image-2.5-flare`, and `gpt-image-2.5-flare-2026-09-08`, arbitrary resolutions are supported as `WIDTHxHEIGHT` strings, for example `1536x864`. Width and height must both be divisible by 16 and the requested aspect ratio must be between 1:3 and 3:1. Resolutions above `2560x1440` are experimental, and the maximum supported resolution is `3840x2160`. The requested size must also satisfy the model's current pixel and edge limits. The standard sizes `1024x1024`, `1536x1024`, and `1024x1536` are supported by the GPT image models; `auto` is supported for models that allow automatic sizing.",
  ),
  'output_format?': type("'png' | 'webp' | 'jpeg' | 'gif' | 'svg'").describe(
    'The output format of the generated image. One of `png`, `webp`, `jpeg`,\n`gif`, or `svg`. Default: `png`. GIF and SVG output require a model\nthat supports the selected format. GIF output does not support\npartial image streaming (`partial_images` greater than `0`),\n`input_image_mask`, or custom `output_compression`.\nResponses lifecycle events can still be streamed for GIF output.\n',
  ),
  'frame_count?': type('number.integer >= 2 & number.integer <= 16').describe(
    'Number of GIF frames. Requires `output_format` to be `gif`. Default: 9.\n',
  ),
  'frame_duration_ms?': type('number.integer >= 20 & number.integer <= 2000').describe(
    'Duration of each GIF frame in milliseconds, rounded to 10 ms.\nRequires `output_format` to be `gif`. Default: 200.\n',
  ),
  'svg?': SvgParamSchema.describe(
    'SVG author model settings. Requires `output_format` to be `svg`.\nWhen SVG model selection is enabled, omitting this object uses the\nouter response model. Otherwise, the default SVG author is used and\nexplicit model overrides are unavailable.\n',
  ),
  'output_compression?': type('number.integer >= 0 & number.integer <= 100').describe(
    'Compression level for the output image. Default: 100.\n',
  ),
  'moderation?': type("'auto' | 'low'").describe(
    'Moderation level for the generated image. Default: `auto`.\n',
  ),
  'background?': type("'transparent' | 'opaque' | 'auto'").describe(
    'Set the background of the generated image. One of `transparent`, `opaque`,\nor `auto`. `gpt-image-2.5-sunburst` and `gpt-image-2.5-flare`, including\ntheir `2026-09-08` snapshots, support `opaque` and `transparent`\nbackgrounds. Transparent backgrounds are available for supported GPT Image\nmodels. For `gpt-image-2` and `gpt-image-2-2026-04-21`, this support is in\npreview. When using `transparent`, set the output format to `png` or `webp`.\nDefault: `auto`.\n',
  ),
  'input_fidelity?': type(InputFidelitySchema).or('null'),
  'input_image_mask?': type({
    'image_url?': type('string').describe('Base64-encoded mask image.\n'),
    'file_id?': type('string').describe('File ID for the mask image.\n'),
    '+': 'reject',
  }).describe(
    'Optional mask for inpainting. Contains `image_url`\n(string, optional) and `file_id` (string, optional).\n',
  ),
  'partial_images?': type('number.integer >= 0 & number.integer <= 3').describe(
    'Number of partial images to generate in streaming mode, from 0 (default value) to 3.\n',
  ),
  'action?': ImageGenActionEnumSchema.describe(
    'Whether to generate a new image or edit an existing image. Default: `auto`.\n',
  ),
})
  .describe('A tool that generates images using the GPT image models.\n')
  .configure({ ref: 'ImageGenTool' })

export type ImageGenTool = typeof ImageGenToolSchema.infer

