export type StopConfiguration = typeof StopConfigurationSchema.infer

export const PredictionContentSchema = type({
  type: type("'content'").describe(
    'The type of the predicted content you want to provide. This type is\ncurrently always `content`.\n',
  ),
  content: type(
    type('string').describe(
      'The content used for a Predicted Output. This is often the\ntext of a file you are regenerating with minor changes.\n',
    ),
  )
    .or(
      type(type(ChatCompletionRequestMessageContentPartTextSchema).array())
        .and(type('unknown[] >= 1'))
        .describe(
          'An array of content parts with a defined type. Supported options differ based on the [model](https://developers.openai.com/api/docs/models) being used to generate the response. Can contain text inputs.',
        ),
    )
    .describe(
      'The content that should be matched when generating a model response.\nIf generated tokens would match this content, the entire model response\ncan be returned much more quickly.\n',
    ),
})
  .describe(
    'Static predicted output content, such as the content of a text file that is\nbeing regenerated.\n',
  )
  .configure({ ref: 'PredictionContent' })

