export const CustomToolChatCompletionsSchema = type({
  type: type("'custom'").describe('The type of the custom tool. Always `custom`.'),
  custom: type({
    name: type('string').describe(
      'The name of the custom tool, used to identify it in tool calls.',
    ),
    'description?': type('string').describe(
      'Optional description of the custom tool, used to provide more context.\n',
    ),
    'format?': type(
      type({
        type: type("'text'").describe('Unconstrained text format. Always `text`.'),
        '+': 'reject',
      }).describe('Unconstrained free-form text.'),
    )
      .or(
        type({
          type: type("'grammar'").describe('Grammar format. Always `grammar`.'),
          grammar: type({
            definition: type('string').describe('The grammar definition.'),
            syntax: type("'lark' | 'regex'").describe(
              'The syntax of the grammar definition. One of `lark` or `regex`.',
            ),
          }).describe('Your chosen grammar.'),
          '+': 'reject',
        }).describe('A grammar defined by the user.'),
      )
      .describe('The input format for the custom tool. Default is unconstrained text.\n'),
  }).describe('Properties of the custom tool.\n'),
})
  .describe('A custom tool that processes input using a specified format.\n')
  .configure({ ref: 'CustomToolChatCompletions' })

export type CustomToolChatCompletions = typeof CustomToolChatCompletionsSchema.infer

export const CreateChatCompletionRequestSchema = type(CreateModelResponsePropertiesSchema)
  .and(
    type({
      'prompt_cache_options?': PromptCacheOptionsParamSchema,
      messages: type(type(ChatCompletionRequestMessageSchema).array())
        .and(type('unknown[] >= 1'))
        .describe(
          'A list of messages comprising the conversation so far. Depending on the\n[model](https://developers.openai.com/api/docs/models) you use, different message types (modalities) are\nsupported, like [text](https://developers.openai.com/api/docs/guides/text),\n[images](https://developers.openai.com/api/docs/guides/images-vision), and [audio](https://developers.openai.com/api/docs/guides/audio).\n',
        ),
      model: ModelIdsSharedSchema.describe(
        'Model ID used to generate the response, like `gpt-6.2-astra`. OpenAI\noffers a wide range of models with different capabilities, performance\ncharacteristics, and price points. Refer to the [model guide](https://developers.openai.com/api/docs/models)\nto browse and compare available models.\n',
      ),
      'service_tier?': ServiceTierSchema,
      'modalities?': ResponseModalitiesSchema,
      'verbosity?': VerbositySchema,
      'reasoning_effort?': ReasoningEffortSchema,
      'max_completion_tokens?': type('number.integer | null').describe(
        'An upper bound for the number of tokens that can be generated for a completion, including visible output tokens and [reasoning tokens](https://developers.openai.com/api/docs/guides/reasoning).\n',
      ),
      'frequency_penalty?': type('number >= -2 & number <= 2 | null').describe(
        "Number between -2.0 and 2.0. Positive values penalize new tokens based on\ntheir existing frequency in the text so far, decreasing the model's\nlikelihood to repeat the same line verbatim.\n",
      ),
      'presence_penalty?': type('number >= -2 & number <= 2 | null').describe(
        "Number between -2.0 and 2.0. Positive values penalize new tokens based on\nwhether they appear in the text so far, increasing the model's likelihood\nto talk about new topics.\n",
      ),
      'web_search_options?': type({
        'user_location?': type(
          type({
            type: type("'approximate'").describe(
              'The type of location approximation. Always `approximate`.\n',
            ),
            approximate: WebSearchLocationSchema,
          }),
        )
          .or('null')
          .describe('Approximate location parameters for the search.\n'),
        'search_context_size?': WebSearchContextSizeSchema,
      }).describe(
        'This tool searches the web for relevant results to use in a response.\nLearn more about the [web search tool](https://developers.openai.com/api/docs/guides/tools-web-search).\n',
      ),
      'top_logprobs?': type('number.integer >= 0 & number.integer <= 20 | null').describe(
        'An integer between 0 and 20 specifying the maximum number of most likely\ntokens to return at each token position, each with an associated log\nprobability. In some cases, the number of returned tokens may be fewer than\nrequested.\n`logprobs` must be set to `true` if this parameter is used.\n',
      ),
      'response_format?': type(
        type(type(ResponseFormatTextSchema).and({ type: "'ResponseFormatText'" })).or(
          type(ResponseFormatJsonSchemaSchema).and({ type: "'ResponseFormatJsonSchema'" }),
        ),
      )
        .or(type(ResponseFormatJsonObjectSchema).and({ type: "'ResponseFormatJsonObject'" }))
        .describe(
          'An object specifying the format that the model must output.\n\nSetting to `{ "type": "json_schema", "json_schema": {...} }` enables\nStructured Outputs which ensures the model will match your supplied JSON\nschema. Learn more in the [Structured Outputs\nguide](https://developers.openai.com/api/docs/guides/structured-outputs).\n\nSetting to `{ "type": "json_object" }` enables the older JSON mode, which\nensures the message the model generates is valid JSON. Using `json_schema`\nis preferred for models that support it.\n',
        ),
      'audio?': type(
        type({
          voice: VoiceIdsOrCustomVoiceSchema.describe(
            'The voice the model uses to respond. Supported built-in voices are\n`alloy`, `ash`, `ballad`, `coral`, `echo`, `fable`, `nova`, `onyx`,\n`sage`, `shimmer`, `marin`, and `cedar`. You may also provide a\ncustom voice object with an `id`, for example `{ "id": "voice_1234" }`.\nCustom voices must be created from audio samples. Voices created from text\nprompts are supported only in Live.\n',
          ),
          format: type("'wav' | 'aac' | 'mp3' | 'flac' | 'opus' | 'pcm16'").describe(
            'Specifies the output audio format. Must be one of `wav`, `mp3`, `flac`,\n`opus`, or `pcm16`.\n',
          ),
        }),
      )
        .or('null')
        .describe(
          'Parameters for audio output. Required when audio output is requested with\n`modalities: ["audio"]`. [Learn more](https://developers.openai.com/api/docs/guides/audio).\n',
        ),
      'store?': type('boolean | null').describe(
        'Whether or not to store the output of this chat completion request for\nuse in our [model distillation](https://developers.openai.com/api/docs/guides/supervised-fine-tuning#distilling-from-a-larger-model) or\n[evals](https://developers.openai.com/api/docs/guides/evals) products.\n\nSupports text and image inputs. Note: image inputs over 8MB will be dropped.\n',
      ),
      'moderation?': type(
        ModerationParamSchema.describe(
          'Configuration for running moderation on the request input and generated output.\n',
        ),
      ).or('null'),
      'stream?': type('boolean | null').describe(
        'If set to true, the model response data will be streamed to the client\nas it is generated using [server-sent events](https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events/Using_server-sent_events#Event_stream_format).\nSee the [Streaming section below](https://developers.openai.com/api/reference/resources/chat/subresources/completions/streaming-events)\nfor more information, along with the [streaming responses](https://developers.openai.com/api/docs/guides/streaming-responses)\nguide for more information on how to handle the streaming events.\n',
      ),
      'stop?': StopConfigurationSchema,
      'logit_bias?': type(type({ '[string]': 'number.integer' }))
        .or('null')
        .describe(
          'Modify the likelihood of specified tokens appearing in the completion.\n\nAccepts a JSON object that maps tokens (specified by their token ID in the\ntokenizer) to an associated bias value from -100 to 100. Mathematically,\nthe bias is added to the logits generated by the model prior to sampling.\nThe exact effect will vary per model, but values between -1 and 1 should\ndecrease or increase likelihood of selection; values like -100 or 100\nshould result in a ban or exclusive selection of the relevant token.\n',
        ),
      'logprobs?': type('boolean | null').describe(
        'Whether to return log probabilities of the output tokens or not. If true,\nreturns the log probabilities of each output token returned in the\n`content` of `message`.\n',
      ),
      'max_tokens?': type('number.integer | null').describe(
        'The maximum number of [tokens](https://platform.openai.com/tokenizer) that can be generated in the\nchat completion. This value can be used to control\n[costs](https://openai.com/api/pricing/) for text generated via API.\n\nThis value is now deprecated in favor of `max_completion_tokens`, and is\nnot compatible with [o-series models](https://developers.openai.com/api/docs/guides/reasoning).\n',
      ),
      'n?': type('number.integer >= 1 & number.integer <= 128 | null').describe(
        'How many chat completion choices to generate for each input message. Omit `n` to generate one choice. Newer models reject an explicit `n`, even `n=1`. When requesting multiple choices, you are billed for generated tokens across all choices.',
      ),
      'prediction?': type(PredictionContentSchema)
        .or('null')
        .describe(
          'Configuration for a [Predicted Output](https://developers.openai.com/api/docs/guides/predicted-outputs),\nwhich can greatly improve response times when large parts of the model\nresponse are known ahead of time. This is most common when you are\nregenerating a file with only minor changes to most of the content.\n',
        ),
      'seed?': type(
        type('bigint | number.integer')
          .or(/^-?\d+$/)
          .pipe((data) => BigInt(data))
          .narrow(
            (data, ctx) =>
              (data >= -9223372036854775808n && data <= 9223372036854775807n) ||
              ctx.mustBe('an int64'),
          )
          .narrow(
            (data, ctx) =>
              data >= -9223372036854775808n || ctx.mustBe('at least -9223372036854775808'),
          )
          .narrow(
            (data, ctx) =>
              data <= 9223372036854775808n || ctx.mustBe('at most 9223372036854775808'),
          ),
      )
        .or('null')
        .describe(
          'This feature is in Beta.\nIf specified, our system will make a best effort to sample deterministically, such that repeated requests with the same `seed` and parameters should return the same result.\nDeterminism is not guaranteed, and you should refer to the `system_fingerprint` response parameter to monitor changes in the backend.\n',
        ),
      'stream_options?': ChatCompletionStreamOptionsSchema,
      'tools?': type(type(ChatCompletionToolSchema).or(CustomToolChatCompletionsSchema))
        .array()
        .describe(
          'A list of tools the model may call. You can provide either\n[custom tools](https://developers.openai.com/api/docs/guides/function-calling#custom-tools) or\n[function tools](https://developers.openai.com/api/docs/guides/function-calling).\n',
        ),
      'tool_choice?': ChatCompletionToolChoiceOptionSchema,
      'parallel_tool_calls?': ParallelToolCallsSchema,
      'function_call?': type(
        type("'none' | 'auto'").describe(
          '`none` means the model will not call a function and instead generates a message. `auto` means the model can pick between generating a message or calling a function.\n',
        ),
      )
        .or(ChatCompletionFunctionCallOptionSchema)
        .describe(
          'Deprecated in favor of `tool_choice`.\n\nControls which (if any) function is called by the model.\n\n`none` means the model will not call a function and instead generates a\nmessage.\n\n`auto` means the model can pick between generating a message or calling a\nfunction.\n\nSpecifying a particular function via `{"name": "my_function"}` forces the\nmodel to call that function.\n\n`none` is the default when no functions are present. `auto` is the default\nif functions are present.\n',
        ),
      'functions?': type(type(ChatCompletionFunctionsSchema).array())
        .and(type('1 <= unknown[] <= 128'))
        .describe(
          'Deprecated in favor of `tools`.\n\nA list of functions the model may generate JSON inputs for.\n',
        ),
    }),
  )
  .configure({ ref: 'CreateChatCompletionRequest' })

