export const CreateEmbeddingRequestSchema = type({
  input: type(
    type(
      type(type('string').describe('The string that will be turned into an embedding.')).or(
        type('string[]')
          .and(type('1 <= unknown[] <= 2048'))
          .describe('The array of strings that will be turned into an embedding.'),
      ),
    ).or(
      type('number.integer[]')
        .and(type('1 <= unknown[] <= 2048'))
        .describe('The array of integers that will be turned into an embedding.'),
    ),
  )
    .or(
      type(type(type('number.integer[]').and(type('unknown[] >= 1'))).array())
        .and(type('1 <= unknown[] <= 2048'))
        .describe('The array of arrays containing integers that will be turned into an embedding.'),
    )
    .describe(
      'Input text to embed, encoded as a string or array of tokens. To embed multiple inputs in a single request, pass an array of strings or array of token arrays. The input must not exceed the max input tokens for the model (8192 tokens for all embedding models), cannot be an empty string, and any array must be 2048 dimensions or less. [Example Python code](https://cookbook.openai.com/examples/how_to_count_tokens_with_tiktoken) for counting tokens. In addition to the per-input token limit, all embedding models enforce a maximum of 300,000 tokens summed across all inputs in a single request.\n',
    ),
  model: type(
    "string | 'text-embedding-ada-002' | 'text-embedding-3-small' | 'text-embedding-3-large'",
  ).describe(
    'ID of the model to use. You can use the [List models](https://developers.openai.com/api/reference/resources/models/methods/list) API to see all of your available models, or see our [Model overview](https://developers.openai.com/api/docs/models) for descriptions of them.\n',
  ),
  'encoding_format?': type("'float' | 'base64'").describe(
    'The format to return the embeddings in. Can be either `float` or [`base64`](https://pypi.org/project/pybase64/).',
  ),
  'dimensions?': type('number.integer >= 1').describe(
    'The number of dimensions the resulting output embeddings should have. Only supported in `text-embedding-3` and later models.\n',
  ),
  'user?': type('string').describe(
    'A unique identifier representing your end-user, which can help OpenAI to monitor and detect abuse. [Learn more](https://developers.openai.com/api/docs/guides/safety-best-practices#implement-safety-identifiers).\n',
  ),
  '+': 'reject',
}).configure({ ref: 'CreateEmbeddingRequest' })

export type CreateEmbeddingRequest = typeof CreateEmbeddingRequestSchema.infer

