export const CreateMessageRequestSchema = type({
  role: type("'user' | 'assistant'").describe(
    'The role of the entity that is creating the message. Allowed values include:\n- `user`: Indicates the message is sent by an actual user and should be used in most cases to represent user-generated messages.\n- `assistant`: Indicates the message is generated by the assistant. Use this value to insert messages from the assistant into the conversation.\n',
  ),
  content: type(type('string').describe('The text contents of the message.')).or(
    type(
      type(
        type(type(MessageContentImageFileObjectSchema).or(MessageContentImageUrlObjectSchema)).or(
          MessageRequestContentTextObjectSchema,
        ),
      ).array(),
    )
      .and(type('unknown[] >= 1'))
      .describe(
        'An array of content parts with a defined type, each can be of type `text` or images can be passed with `image_url` or `image_file`. Image types are only supported on [Vision-compatible models](https://developers.openai.com/api/docs/models).',
      ),
  ),
  'attachments?': type(
    type(
      type({
        'file_id?': type('string').describe('The ID of the file to attach to the message.'),
        'tools?': type(type(AssistantToolsCodeSchema).or(AssistantToolsFileSearchTypeOnlySchema))
          .array()
          .describe('The tools to add this file to.'),
      }),
    )
      .array()
      .describe('A list of files attached to the message, and the tools they should be added to.'),
  ).or('null'),
  'metadata?': MetadataSchema,
  '+': 'reject',
}).configure({ ref: 'CreateMessageRequest' })

export type CreateMessageRequest = typeof CreateMessageRequestSchema.infer

export const CreateModerationRequestSchema = type({
  input: type(
    type(type('string').describe('A string of text to classify for moderation.')).or(
      type('string[]').describe('An array of strings to classify for moderation.'),
    ),
  )
    .or(
      type(
        type(
          type({
            type: type("'image_url'").describe('Always `image_url`.'),
            image_url: type({
              url: type('string.url').describe(
                'Either a URL of the image or the base64 encoded image data.',
              ),
            }).describe('Contains either an image URL or a data URL for a base64 encoded image.'),
          }).describe('An object describing an image to classify.'),
        ).or(
          type({
            type: type("'text'").describe('Always `text`.'),
            text: type('string').describe('A string of text to classify.'),
          }).describe('An object describing text to classify.'),
        ),
      )
        .array()
        .describe('An array of multi-modal inputs to the moderation model.'),
    )
    .describe(
      'Input (or inputs) to classify. Can be a single string, an array of strings, or\nan array of multi-modal input objects similar to other models.\n',
    ),
  'model?': type(
    "string | 'omni-moderation-latest' | 'omni-moderation-2024-09-26' | 'omni-moderation-csam-latest' | 'text-moderation-latest' | 'text-moderation-stable'",
  ).describe(
    'The content moderation model you would like to use. Learn more in\n[the moderation guide](https://developers.openai.com/api/docs/guides/moderation), and learn about\navailable models [here](https://developers.openai.com/api/docs/guides/moderation).\nApproved organizations can use `omni-moderation-csam-latest` with a single `image_url` input.\n',
  ),
}).configure({ ref: 'CreateModerationRequest' })

export type CreateModerationRequest = typeof CreateModerationRequestSchema.infer

