export const CreateVoicePromptRequestSchema = type({
  type: type("'prompt'").describe('Set to `prompt` to create a voice from a text description.'),
  name: type('string')
    .narrow((data, ctx) => [...data].length >= 1 || ctx.mustBe('at least 1 character'))
    .narrow((data, ctx) => [...data].length <= 256 || ctx.mustBe('at most 256 characters'))
    .describe('The name of the new voice.'),
  prompt: type('string')
    .narrow((data, ctx) => [...data].length >= 1 || ctx.mustBe('at least 1 character'))
    .narrow((data, ctx) => [...data].length <= 2000 || ctx.mustBe('at most 2000 characters'))
    .describe('A description of the desired voice. Must not contain only whitespace.'),
  'script_hint?': type('string')
    .narrow((data, ctx) => [...data].length >= 1 || ctx.mustBe('at least 1 character'))
    .narrow((data, ctx) => [...data].length <= 2000 || ctx.mustBe('at most 2000 characters'))
    .describe(
      'Optional text for the voice to speak during creation. If omitted, a script is generated from the prompt. Must not be blank after trimming whitespace; scripts that are too short are rejected.',
    ),
  'model?': type("string | 'auto' | '2026-10-08'").describe(
    'The voice creation model to use. Defaults to `auto`.',
  ),
  '+': 'reject',
})
  .describe(
    'Creates a synthetic voice from a text description. Supports application/json or multipart/form-data.',
  )
  .configure({ ref: 'CreateVoicePromptRequest' })

export type CreateVoicePromptRequest = typeof CreateVoicePromptRequestSchema.infer

export const CreateVoiceRequestSchema = type(
  type(CreateVoiceFromConsentRequestSchema).and({ type: "'audio_sample'" }),
)
  .or(type(CreateVoicePromptRequestSchema).and({ type: "'prompt'" }))
  .configure({ ref: 'CreateVoiceRequest' })

export type CreateVoiceRequest = typeof CreateVoiceRequestSchema.infer

