export const EvalRunSchema = type({
  object: type("'eval.run'").describe('The type of the object. Always "eval.run".'),
  id: type('string').describe('Unique identifier for the evaluation run.'),
  eval_id: type('string').describe('The identifier of the associated evaluation.'),
  status: type('string').describe('The status of the evaluation run.'),
  model: type('string | null').describe('The model that is evaluated, if applicable.'),
  name: type('string | null').describe('The name of the evaluation run.'),
  created_at: type('number.integer').describe(
    'Unix timestamp (in seconds) when the evaluation run was created.',
  ),
  report_url: type('string.url').describe(
    'The URL to the rendered evaluation run report on the UI dashboard.',
  ),
  result_counts: type({
    total: type('number.integer').describe('Total number of executed output items.'),
    errored: type('number.integer').describe('Number of output items that resulted in an error.'),
    failed: type('number.integer').describe(
      'Number of output items that failed to pass the evaluation.',
    ),
    passed: type('number.integer').describe('Number of output items that passed the evaluation.'),
  }).describe('Counters summarizing the outcomes of the evaluation run.'),
  per_model_usage: type(
    type(
      type({
        model_name: type('string').describe('The name of the model.'),
        invocation_count: type('number.integer').describe('The number of invocations.'),
        prompt_tokens: type('number.integer').describe('The number of prompt tokens used.'),
        completion_tokens: type('number.integer').describe(
          'The number of completion tokens generated.',
        ),
        total_tokens: type('number.integer').describe('The total number of tokens used.'),
        cached_tokens: type('number.integer').describe(
          'The number of tokens retrieved from cache.',
        ),
      }),
    ).array(),
  )
    .or('null')
    .describe('Usage statistics for each model during the evaluation run.'),
  per_testing_criteria_results: type(
    type(
      type({
        testing_criteria: type('string').describe('A description of the testing criteria.'),
        passed: type('number.integer').describe('Number of tests passed for this criteria.'),
        failed: type('number.integer').describe('Number of tests failed for this criteria.'),
      }),
    ).array(),
  )
    .or('null')
    .describe('Results per testing criteria applied during the evaluation run.'),
  data_source: type(
    type(CreateEvalJsonlRunDataSourceSchema).or(CreateEvalCompletionsRunDataSourceSchema),
  )
    .or(CreateEvalResponsesRunDataSourceSchema)
    .describe("Information about the run's data source."),
  metadata: MetadataSchema,
  error: type(EvalApiErrorSchema).or('null'),
})
  .describe('A schema representing an evaluation run.\n')
  .configure({ ref: 'EvalRun' })

export type EvalRun = typeof EvalRunSchema.infer

