export const FineTuningIntegrationSchema = type({
  type: type("'wandb'").describe(
    'The type of the integration being enabled for the fine-tuning job',
  ),
  wandb: type({
    project: type('string').describe(
      'The name of the project that the new run will be created under.\n',
    ),
    'name?': type(
      type('string').describe(
        'A display name to set for the run. If not set, we will use the Job ID as the name.\n',
      ),
    ).or('null'),
    'entity?': type(
      type('string').describe(
        'The entity to use for the run. This allows you to set the team or username of the WandB user that you would\nlike associated with the run. If not set, the default entity for the registered WandB API key is used.\n',
      ),
    ).or('null'),
    'tags?': type('string[]').describe(
      'A list of tags to be attached to the newly created run. These tags are passed through directly to WandB. Some\ndefault tags are generated by OpenAI: "openai/finetune", "openai/{base-model}", "openai/{ftjob-abcdef}".\n',
    ),
  }).describe(
    'The settings for your integration with Weights and Biases. This payload specifies the project that\nmetrics will be sent to. Optionally, you can set an explicit display name for your run, add tags\nto your run, and set a default entity (team, username, etc) to be associated with your run.\n',
  ),
}).configure({ ref: 'FineTuningIntegration' })

export type FineTuningIntegration = typeof FineTuningIntegrationSchema.infer

export const FineTuningJobSchema = type({
  id: type('string').describe(
    'The object identifier, which can be referenced in the API endpoints.',
  ),
  created_at: type('number.integer').describe(
    'The Unix timestamp (in seconds) for when the fine-tuning job was created.',
  ),
  error: type(
    type(
      type({
        code: type('string').describe('A machine-readable error code.'),
        message: type('string').describe('A human-readable error message.'),
        param: type(
          type('string').describe(
            'The parameter that was invalid, usually `training_file` or `validation_file`. This field will be null if the failure was not parameter-specific.',
          ),
        ).or('null'),
      }).describe(
        'For fine-tuning jobs that have `failed`, this will contain more information on the cause of the failure.',
      ),
    ).or('null'),
  ).or(type({})),
  fine_tuned_model: type(
    type('string').describe(
      'The name of the fine-tuned model that is being created. The value will be null if the fine-tuning job is still running.',
    ),
  ).or('null'),
  finished_at: type(
    type('number.integer').describe(
      'The Unix timestamp (in seconds) for when the fine-tuning job was finished. The value will be null if the fine-tuning job is still running.',
    ),
  ).or('null'),
  'hyperparameters?': type(
    type({
      'batch_size?': type(
        type("'auto' | number.integer >= 1 & number.integer <= 256").describe(
          'Number of examples in each batch. A larger batch size means that model parameters\nare updated less frequently, but with lower variance.\n',
        ),
      ).or('null'),
      'learning_rate_multiplier?': type("'auto' | number > 0").describe(
        'Scaling factor for the learning rate. A smaller learning rate may be useful to avoid\noverfitting.\n',
      ),
      'n_epochs?': type("'auto' | number.integer >= 1 & number.integer <= 50").describe(
        'The number of epochs to train the model for. An epoch refers to one full cycle\nthrough the training dataset.\n',
      ),
    }),
  )
    .or('null')
    .describe(
      'The hyperparameters used for the fine-tuning job. This value will only be returned when running `supervised` jobs.',
    ),
  model: type('string').describe('The base model that is being fine-tuned.'),
  object: type("'fine_tuning.job'").describe('The object type, which is always "fine_tuning.job".'),
  organization_id: type('string').describe('The organization that owns the fine-tuning job.'),
  result_files: type('string[]').describe(
    'The compiled results file ID(s) for the fine-tuning job. You can retrieve the results with the [Files API](https://developers.openai.com/api/reference/resources/files/methods/content).',
  ),
  status: type(
    "'validating_files' | 'queued' | 'running' | 'succeeded' | 'failed' | 'cancelled' | 'pausing' | 'paused'",
  ).describe(
    'The current status of the fine-tuning job, which can be `validating_files`, `queued`, `running`, `pausing`, `paused`, `succeeded`, `failed`, or `cancelled`.',
  ),
  trained_tokens: type(
    type('number.integer').describe(
      'The total number of billable tokens processed by this fine-tuning job. The value will be null if the fine-tuning job is still running.',
    ),
  ).or('null'),
  training_file: type('string').describe(
    'The file ID used for training. You can retrieve the training data with the [Files API](https://developers.openai.com/api/reference/resources/files/methods/content).',
  ),
  validation_file: type(
    type('string').describe(
      'The file ID used for validation. You can retrieve the validation results with the [Files API](https://developers.openai.com/api/reference/resources/files/methods/content).',
    ),
  ).or('null'),
  'integrations?': type(
    type(type(FineTuningIntegrationSchema).array())
      .and(type('unknown[] <= 5'))
      .describe('A list of integrations to enable for this fine-tuning job.'),
  ).or('null'),
  seed: type('number.integer | null').describe('The seed used for the fine-tuning job.'),
  'estimated_finish?': type(
    type('number.integer').describe(
      'The Unix timestamp (in seconds) for when the fine-tuning job is estimated to finish. The value will be null if the fine-tuning job is not running.',
    ),
  ).or('null'),
  'method?': type(FineTuneMethodSchema).or('null'),
  'metadata?': MetadataSchema,
})
  .narrow(
    (data) =>
      type({ method: type({ type: "'dpo' | 'reinforcement'" }) }).allows(data) ||
      type('unknown').allows(data),
  )
  .describe(
    'The `fine_tuning.job` object represents a fine-tuning job that has been created through the API.\n',
  )
  .configure({ ref: 'FineTuningJob' })

export type FineTuningJob = typeof FineTuningJobSchema.infer

