export const AnswerResourceSchema = type(
  type(
    type(type(AnswerResourcePredicateSchema).and({ type: "'predicate'" })).or(
      type(AnswerResourceChoiceSchema).and({ type: "'choice'" }),
    ),
  ).or(type(AnswerResourceScoreSchema).and({ type: "'score'" })),
)
  .or(type(AnswerResourceRefusalSchema).and({ type: "'refusal'" }))
  .describe('A completed question always includes its name, including null when unnamed.')
  .configure({ ref: 'AnswerResource' })

export type AnswerResource = typeof AnswerResourceSchema.infer

export const InputTokensDetailsResourceSchema = type({
  cached_tokens: type('bigint | number.integer')
    .or(/^-?\d+$/)
    .pipe((data) => BigInt(data))
    .narrow(
      (data, ctx) =>
        (data >= -9223372036854775808n && data <= 9223372036854775807n) || ctx.mustBe('an int64'),
    )
    .narrow((data, ctx) => data >= -2147483648n || ctx.mustBe('at least -2147483648'))
    .narrow((data, ctx) => data <= 2147483647n || ctx.mustBe('at most 2147483647')),
  cache_write_tokens: type('bigint | number.integer')
    .or(/^-?\d+$/)
    .pipe((data) => BigInt(data))
    .narrow(
      (data, ctx) =>
        (data >= -9223372036854775808n && data <= 9223372036854775807n) || ctx.mustBe('an int64'),
    )
    .narrow((data, ctx) => data >= -2147483648n || ctx.mustBe('at least -2147483648'))
    .narrow((data, ctx) => data <= 2147483647n || ctx.mustBe('at most 2147483647')),
  '+': 'reject',
}).configure({ ref: 'InputTokensDetailsResource' })

export type InputTokensDetailsResource = typeof InputTokensDetailsResourceSchema.infer

