export const RealtimeBetaResponseCreateParamsSchema = type({
  'modalities?': type("'text' | 'audio'")
    .array()
    .describe(
      'The set of modalities the model can respond with. To disable audio,\nset this to ["text"].\n',
    ),
  'instructions?': type('string').describe(
    'The default system instructions (i.e. system message) prepended to model \ncalls. This field allows the client to guide the model on desired \nresponses. The model can be instructed on response content and format, \n(e.g. "be extremely succinct", "act friendly", "here are examples of good \nresponses") and on audio behavior (e.g. "talk quickly", "inject emotion \ninto your voice", "laugh frequently"). The instructions are not guaranteed \nto be followed by the model, but they provide guidance to the model on the \ndesired behavior.\n\nNote that the server sets default instructions which will be used if this \nfield is not set and are visible in the `session.created` event at the \nstart of the session.\n',
  ),
  'voice?': VoiceIdsOrCustomVoiceSchema.describe(
    'The voice the model uses to respond. Supported built-in voices are\n`alloy`, `ash`, `ballad`, `coral`, `echo`, `sage`, `shimmer`, `verse`,\n`marin`, and `cedar`. You may also provide a custom voice object with an\n`id`, for example `{ "id": "voice_1234" }`. Voice cannot be changed during\nthe session once the model has responded with audio at least once.\nCustom voices must be created from audio samples. Voices created from text prompts are supported only in Live.\n',
  ),
  'output_audio_format?': type("'pcm16' | 'g711_ulaw' | 'g711_alaw'").describe(
    'The format of output audio. Options are `pcm16`, `g711_ulaw`, or `g711_alaw`.\n',
  ),
  'tools?': type(
    type({
      'type?': type("'function'").describe('The type of the tool, i.e. `function`.'),
      'name?': type('string').describe('The name of the function.'),
      'description?': type('string').describe(
        'The description of the function, including guidance on when and how \nto call it, and guidance about what to tell the user when calling \n(if anything).\n',
      ),
      'parameters?': type({}).describe('Parameters of the function in JSON Schema.'),
    }),
  )
    .array()
    .describe('Tools (functions) available to the model.'),
  'tool_choice?': type(type(ToolChoiceOptionsSchema).or(ToolChoiceFunctionSchema))
    .or(ToolChoiceMCPSchema)
    .describe(
      'How the model chooses tools. Provide one of the string modes or force a specific\nfunction/MCP tool.\n',
    ),
  'temperature?': type('number').describe(
    'Sampling temperature for the model, limited to [0.6, 1.2]. Defaults to 0.8.\n',
  ),
  'max_output_tokens?': type("number.integer | 'inf'").describe(
    'Maximum number of output tokens for a single assistant response,\ninclusive of tool calls. Provide an integer between 1 and 4096 to\nlimit output tokens, or `inf` for the maximum available tokens for a\ngiven model. Defaults to `inf`.\n',
  ),
  'conversation?': type("string | 'auto' | 'none'").describe(
    'Controls which conversation the response is added to. Currently supports\n`auto` and `none`, with `auto` as the default value. The `auto` value\nmeans that the contents of the response will be added to the default\nconversation. Set this to `none` to create an out-of-band response which \nwill not add items to default conversation.\n',
  ),
  'metadata?': MetadataSchema,
  'prompt?': PromptSchema,
  'input?': type(RealtimeConversationItemSchema)
    .array()
    .describe(
      'Input items to include in the prompt for the model. Using this field\ncreates a new context for this Response instead of using the default\nconversation. An empty array `[]` will clear the context for this Response.\nNote that this can include references to items from the default conversation.\n',
    ),
})
  .describe('Create a new Realtime response with these parameters')
  .configure({ ref: 'RealtimeBetaResponseCreateParams' })

export type RealtimeBetaResponseCreateParams = typeof RealtimeBetaResponseCreateParamsSchema.infer

export const RealtimeBetaClientEventResponseCreateSchema = type({
  'event_id?': type('string').describe('Optional client-generated ID used to identify this event.'),
  type: type("'response.create'").describe('The event type, must be `response.create`.'),
  'response?': RealtimeBetaResponseCreateParamsSchema,
})
  .describe(
    "This event instructs the server to create a Response, which means triggering \nmodel inference. When in Server VAD mode, the server will create Responses \nautomatically.\n\nA Response will include at least one Item, and may have two, in which case \nthe second will be a function call. These Items will be appended to the \nconversation history.\n\nThe server will respond with a `response.created` event, events for Items \nand content created, and finally a `response.done` event to indicate the \nResponse is complete.\n\nThe `response.create` event can optionally include inference configuration like \n`instructions`, and `temperature`. These fields will override the Session's \nconfiguration for this Response only.\n\nResponses can be created out-of-band of the default Conversation, meaning that they can\nhave arbitrary input, and it's possible to disable writing the output to the Conversation.\nOnly one Response can write to the default Conversation at a time, but otherwise multiple\nResponses can be created in parallel.\n\nClients can set `conversation` to `none` to create a Response that does not write to the default\nConversation. Arbitrary input can be provided with the `input` field, which is an array accepting\nraw Items and references to existing Items.\n",
  )
  .configure({ ref: 'RealtimeBetaClientEventResponseCreate' })

export type RealtimeBetaClientEventResponseCreate =
  typeof RealtimeBetaClientEventResponseCreateSchema.infer

export const RealtimeTruncationSchema = type(
  type("'auto' | 'disabled'").describe(
    'The truncation strategy to use for the session. `auto` is the default truncation strategy. `disabled` will disable truncation and emit errors when the conversation exceeds the input token limit.',
  ),
)
  .or(
    type({
      type: type("'retention_ratio'").describe('Use retention ratio truncation.'),
      retention_ratio: type('number >= 0 & number <= 1').describe(
        'Fraction of post-instruction conversation tokens to retain (`0.0` - `1.0`) when the conversation exceeds the input token limit. Setting this to `0.8` means that messages will be dropped until 80% of the maximum allowed tokens are used. This helps reduce the frequency of truncations and improve cache rates.\n',
      ),
      'token_limits?': type({
        'post_instructions?': type('number.integer >= 0').describe(
          "Maximum tokens allowed in the conversation after instructions (which including tool definitions). For example, setting this to 5,000 would mean that truncation would occur when the conversation exceeds 5,000 tokens after instructions. This cannot be higher than the model's context window size minus the maximum output tokens.",
        ),
      }).describe(
        "Optional custom token limits for this truncation strategy. If not provided, the model's default token limits will be used.",
      ),
    }).describe(
      'Retain a fraction of the conversation tokens when the conversation exceeds the input token limit. This allows you to amortize truncations across multiple turns, which can help improve cached token usage.',
    ),
  )
  .describe(
    "When the number of tokens in a conversation exceeds the model's input token limit, the conversation be truncated, meaning messages (starting from the oldest) will not be included in the model's context. A 32k context model with 4,096 max output tokens can only include 28,224 tokens in the context before truncation occurs.\n\nClients can configure truncation behavior to truncate with a lower max token limit, which is an effective way to control token usage and cost.\n\nTruncation will reduce the number of cached tokens on the next turn (busting the cache), since messages are dropped from the beginning of the context. However, clients can also configure truncation to retain messages up to a fraction of the maximum context size, which will reduce the need for future truncations and thus improve the cache rate.\n\nTruncation can be disabled entirely, which means the server will never truncate but would instead return an error if the conversation exceeds the model's input token limit.\n",
  )
  .configure({ ref: 'RealtimeTruncation' })

export type RealtimeTruncation = typeof RealtimeTruncationSchema.infer

