export type RealtimeSessionCreateRequest = typeof RealtimeSessionCreateRequestSchema.infer

export const RealtimeBetaClientEventSessionUpdateSchema = type({
  'event_id?': type('string').describe('Optional client-generated ID used to identify this event.'),
  type: type("'session.update'").describe('The event type, must be `session.update`.'),
  session: RealtimeSessionCreateRequestSchema,
})
  .describe(
    'Send this event to update the session’s default configuration.\nThe client may send this event at any time to update any field,\nexcept for `voice`. However, note that once a session has been\ninitialized with a particular `model`, it can’t be changed to\nanother model using `session.update`.\n\nWhen the server receives a `session.update`, it will respond\nwith a `session.updated` event showing the full, effective configuration.\nOnly the fields that are present are updated. To clear a field like\n`instructions`, pass an empty string.\n',
  )
  .configure({ ref: 'RealtimeBetaClientEventSessionUpdate' })

export type RealtimeBetaClientEventSessionUpdate =
  typeof RealtimeBetaClientEventSessionUpdateSchema.infer

export const RealtimeTranscriptionSessionCreateRequestSchema = type({
  'turn_detection?': type({
    'type?': type("'server_vad'").describe(
      'Type of turn detection. Only `server_vad` is currently supported for transcription sessions.\n',
    ),
    'threshold?': type('number').describe(
      'Activation threshold for VAD (0.0 to 1.0), this defaults to 0.5. A\nhigher threshold will require louder audio to activate the model, and\nthus might perform better in noisy environments.\n',
    ),
    'prefix_padding_ms?': type('number.integer').describe(
      'Amount of audio to include before the VAD detected speech (in\nmilliseconds). Defaults to 300ms.\n',
    ),
    'silence_duration_ms?': type('number.integer').describe(
      'Duration of silence to detect speech stop (in milliseconds). Defaults\nto 500ms. With shorter values the model will respond more quickly,\nbut may jump in on short pauses from the user.\n',
    ),
  }).describe(
    'Configuration for turn detection. Can be set to `null` to turn off. Server VAD means that the model will detect the start and end of speech based on audio volume and respond at the end of user speech.\n',
  ),
  'input_audio_noise_reduction?': type('unknown')
    .narrow(
      (data: unknown) =>
        !Array.isArray(data) &&
        typeof data !== 'string' &&
        typeof data !== 'number' &&
        typeof data !== 'boolean',
    )
    .describe(
      'Configuration for input audio noise reduction. This can be set to `null` to turn off.\nNoise reduction filters audio added to the input audio buffer before it is sent to VAD and the model.\nFiltering the audio can improve VAD and turn detection accuracy (reducing false positives) and model performance by improving perception of the input audio.\n',
    ),
  'input_audio_format?': type("'pcm16' | 'g711_ulaw' | 'g711_alaw'").describe(
    'The format of input audio. Options are `pcm16`, `g711_ulaw`, or `g711_alaw`.\nFor `pcm16`, input audio must be 16-bit PCM at a 24kHz sample rate,\nsingle channel (mono), and little-endian byte order.\n',
  ),
  'input_audio_transcription?': AudioTranscriptionSchema.describe(
    'Configuration for input audio transcription. The client can optionally set the language and prompt for transcription, these offer additional guidance to the transcription service.\n',
  ),
  'include?': type("'item.input_audio_transcription.logprobs'[]").describe(
    'The set of items to include in the transcription. Current available items are:\n`item.input_audio_transcription.logprobs`\n',
  ),
})
  .describe('Realtime transcription session object configuration.')
  .configure({ ref: 'RealtimeTranscriptionSessionCreateRequest' })

export type RealtimeTranscriptionSessionCreateRequest =
  typeof RealtimeTranscriptionSessionCreateRequestSchema.infer

