export const RealtimeBetaResponseSchema = type({
  'id?': type('string').describe('The unique ID of the response.'),
  'object?': type("'realtime.response'").describe('The object type, must be `realtime.response`.'),
  'status?': type("'completed' | 'cancelled' | 'failed' | 'incomplete' | 'in_progress'").describe(
    'The final status of the response (`completed`, `cancelled`, `failed`, or \n`incomplete`, `in_progress`).\n',
  ),
  'status_details?': type({
    'type?': type("'completed' | 'cancelled' | 'failed' | 'incomplete'").describe(
      'The type of error that caused the response to fail, corresponding \nwith the `status` field (`completed`, `cancelled`, `incomplete`, \n`failed`).\n',
    ),
    'reason?': type(
      "'turn_detected' | 'client_cancelled' | 'max_output_tokens' | 'content_filter'",
    ).describe(
      'The reason the Response did not complete. For a `cancelled` Response, \none of `turn_detected` (the server VAD detected a new start of speech) \nor `client_cancelled` (the client sent a cancel event). For an \n`incomplete` Response, one of `max_output_tokens` or `content_filter` \n(the server-side safety filter activated and cut off the response).\n',
    ),
    'error?': type({
      'type?': type('string').describe('The type of error.'),
      'code?': type('string').describe('Error code, if any.'),
      'message?': type('string').describe('A human-readable error message.'),
    }).describe(
      'A description of the error that caused the response to fail, \npopulated when the `status` is `failed`.\n',
    ),
  }).describe('Additional details about the status.'),
  'output?': type(RealtimeConversationItemSchema)
    .array()
    .describe('The list of output items generated by the response.'),
  'metadata?': MetadataSchema,
  'usage?': type({
    'total_tokens?': type('number.integer').describe(
      'The total number of tokens in the Response including input and output \ntext and audio tokens.\n',
    ),
    'input_tokens?': type('number.integer').describe(
      'The number of input tokens used in the Response, including text and \naudio tokens.\n',
    ),
    'output_tokens?': type('number.integer').describe(
      'The number of output tokens sent in the Response, including text and \naudio tokens.\n',
    ),
    'input_token_details?': type({
      'cached_tokens?': type('number.integer').describe(
        'The number of cached tokens used as input for the Response.',
      ),
      'text_tokens?': type('number.integer').describe(
        'The number of text tokens used as input for the Response.',
      ),
      'image_tokens?': type('number.integer').describe(
        'The number of image tokens used as input for the Response.',
      ),
      'audio_tokens?': type('number.integer').describe(
        'The number of audio tokens used as input for the Response.',
      ),
      'cached_tokens_details?': type({
        'text_tokens?': type('number.integer').describe(
          'The number of cached text tokens used as input for the Response.',
        ),
        'image_tokens?': type('number.integer').describe(
          'The number of cached image tokens used as input for the Response.',
        ),
        'audio_tokens?': type('number.integer').describe(
          'The number of cached audio tokens used as input for the Response.',
        ),
      }).describe('Details about the cached tokens used as input for the Response.'),
    }).describe('Details about the input tokens used in the Response.'),
    'output_token_details?': type({
      'text_tokens?': type('number.integer').describe(
        'The number of text tokens used in the Response.',
      ),
      'audio_tokens?': type('number.integer').describe(
        'The number of audio tokens used in the Response.',
      ),
    }).describe('Details about the output tokens used in the Response.'),
  }).describe(
    'Usage statistics for the Response, this will correspond to billing. A \nRealtime API session will maintain a conversation context and append new \nItems to the Conversation, thus output from previous turns (text and \naudio tokens) will become the input for later turns.\n',
  ),
  'conversation_id?': type('string').describe(
    'Which conversation the response is added to, determined by the `conversation`\nfield in the `response.create` event. If `auto`, the response will be added to\nthe default conversation and the value of `conversation_id` will be an id like\n`conv_1234`. If `none`, the response will not be added to any conversation and\nthe value of `conversation_id` will be `null`. If responses are being triggered\nby server VAD, the response will be added to the default conversation, thus\nthe `conversation_id` will be an id like `conv_1234`.\n',
  ),
  'voice?': VoiceIdsSharedSchema.describe(
    'The voice the model used to respond.\nCurrent voice options are `alloy`, `ash`, `ballad`, `coral`, `echo`, `sage`,\n`shimmer`, and `verse`.\n',
  ),
  'modalities?': type("'text' | 'audio'")
    .array()
    .describe(
      'The set of modalities the model used to respond. If there are multiple modalities,\nthe model will pick one, for example if `modalities` is `["text", "audio"]`, the model\ncould be responding in either text or audio.\n',
    ),
  'output_audio_format?': type("'pcm16' | 'g711_ulaw' | 'g711_alaw'").describe(
    'The format of output audio. Options are `pcm16`, `g711_ulaw`, or `g711_alaw`.\n',
  ),
  'temperature?': type('number').describe(
    'Sampling temperature for the model, limited to [0.6, 1.2]. Defaults to 0.8.\n',
  ),
  'max_output_tokens?': type("number.integer | 'inf'").describe(
    'Maximum number of output tokens for a single assistant response,\ninclusive of tool calls, that was used in this response.\n',
  ),
})
  .describe('The response resource.')
  .configure({ ref: 'RealtimeBetaResponse' })

export type RealtimeBetaResponse = typeof RealtimeBetaResponseSchema.infer

