export const ResponsesClientEventResponseCreateSchema = type(
  type({
    type: type("'response.create'").describe(
      'The type of the client event. Always `response.create`.\n',
    ),
    'generate?': type('boolean').describe(
      'Whether to generate output for this response. Defaults to true when omitted.\nSet to false to prepare request state without model output; the response\nID can be used as previous_response_id on a later turn.\n',
    ),
    'stream_id?': type('string')
      .and(/^[A-Za-z0-9_.-]+$/)
      .narrow((data, ctx) => [...data].length >= 1 || ctx.mustBe('at least 1 character'))
      .narrow((data, ctx) => [...data].length <= 256 || ctx.mustBe('at most 256 characters'))
      .describe(
        'The WebSocket lane for this response. Requests with the same\n`stream_id` are processed FIFO, and events for the response echo the\nsame `stream_id`.\n\n`stream_id` controls routing; `previous_response_id` controls\nconversation lineage, so a new lane can fork from a response created\non another lane.\n',
      ),
  }),
)
  .and(CreateResponseSchema)
  .describe(
    'Client event for creating a response over a persistent WebSocket connection.\nThis payload uses the same top-level fields as `POST /v1/responses`, plus\nWebSocket-only envelope metadata.\n\nNotes:\n- `stream` is implicit over WebSocket and should not be sent.\n- `background` is not supported over WebSocket.\n- `stream_id` is WebSocket-only and is not part of `POST /v1/responses`.\n',
  )
  .configure({ ref: 'ResponsesClientEventResponseCreate' })

export type ResponsesClientEventResponseCreate =
  typeof ResponsesClientEventResponseCreateSchema.infer

