export const WebhookLiveCallIncomingSchema = type({
  created_at: type('number.integer').describe(
    'The Unix timestamp (in seconds) of when the event was created.\n',
  ),
  id: type('string').describe('The unique ID of the event.\n'),
  data: type({
    session_id: type('string').describe(
      'The `live_...` ID of the pending SIP session. Pass this value unchanged\nto Live call controls and sideband connections. The corresponding\n`realtime.call.incoming` event uses a separate `rtc_...` call ID.\n',
    ),
    'sip_media_security?': type("'rtp' | 'srtp' | string").describe(
      'Media protection selected on the SIP leg during SDP negotiation. `srtp`\nindicates SRTP; `rtp` indicates unencrypted RTP. Omitted when unknown.\nThis does not describe SIP signaling security or confirm that media has\nflowed. Clients should handle unrecognized values as unknown.\n',
    ),
    sip_headers: type(
      type({
        name: type('string').describe('Name of the SIP Header.\n'),
        value: type('string').describe('Value of the SIP Header.\n'),
      }).describe('A header from the SIP Invite.\n'),
    )
      .array()
      .describe(
        'Headers from the SIP INVITE, excluding SIP authorization headers.\nRetained names, values, repeated entries, and order are preserved.\nTreat these values as untrusted call metadata.\n',
      ),
  }).describe('Event data payload.\n'),
  'object?': type("'event'").describe('The object of the event. Always `event`.\n'),
  type: type("'live.call.incoming'").describe(
    'The type of the event. Always `live.call.incoming`.\n',
  ),
})
  .describe(
    'Deprecated: use `live.transport.incoming`. Retained for existing subscriptions\nduring migration; new subscriptions to this event are not allowed.\nSent when an incoming API SIP session is available for Live acceptance. The\nsame pending session can also emit `realtime.call.incoming`; the first\nsuccessful Realtime or Live accept endpoint selects the runtime surface.\n',
  )
  .configure({ ref: 'WebhookLiveCallIncoming' })

export type WebhookLiveCallIncoming = typeof WebhookLiveCallIncomingSchema.infer

