      filters: [
        [
          [
            ['BetaComparisonFilterSchema', '&', { type: "'BetaComparisonFilter'" }],
            '|',
            ['BetaCompoundFilterSchema', '&', { type: "'BetaCompoundFilter'" }],
          ],
          '[]',
        ],
        '@',
        'Array of filters to combine. Items can be `ComparisonFilter` or `CompoundFilter`.',
      ],
      '+': 'reject',
