export const ApiKeyAuthSecurityScheme = { type: 'http', scheme: 'bearer' }
export const AdminApiKeyAuthSecurityScheme = { type: 'http', scheme: 'bearer' }

export const TooManyRequestsResponse = {
  description: 'The request was rejected because a rate limit was exceeded.',
  headers: {
    'Retry-After': {
      description:
        'The minimum number of seconds to wait before retrying. This header is returned when the server has computed a retry delay and may be omitted for 429 responses that require user action.',
      schema: resolver(type('number.integer >= 1')),
    },
  },
  content: { 'application/json': { schema: resolver(ErrorResponseSchema) } },
}
export const InferenceRateLimitedResponse = {
  description:
    'The request was rejected because a rate limit was exceeded. A slow_down error means traffic increased too quickly; reduce your request rate, then increase it gradually.',
  headers: {
    'Retry-After': {
      description:
        'The minimum number of seconds to wait before retrying. This header is returned when the server has computed a retry delay and may be omitted.',
      schema: resolver(type('number.integer >= 1')),
    },
  },
  content: {
    'application/json': {
      schema: resolver(ErrorResponseSchema),
      examples: {
        slowDown: {
          summary: 'Traffic increased too quickly',
          value: {
            error: {
              message:
                'Your request rate increased too quickly. Please reduce the request rate and gradually increase it again.',
              type: 'rate_limit_error',
              param: null,
              code: 'slow_down',
            },
          },
        },
      },
    },
  },
}
export const InferenceServiceUnavailableResponse = {
  description:
    'The service is temporarily unavailable. A server_is_overloaded error means the requested model is temporarily overloaded; retry after a brief delay.',
  headers: {
    'Retry-After': {
      description:
        'The minimum number of seconds to wait before retrying. This header is returned when the server has computed a retry delay and may be omitted.',
      schema: resolver(type('number.integer >= 1')),
    },
  },
  content: {
    'application/json': {
      schema: resolver(ErrorResponseSchema),
      examples: {
        serverOverloaded: {
          summary: 'The requested model is temporarily overloaded',
          value: {
            error: {
              message:
                'The model is temporarily overloaded. Please retry your request after a brief delay.',
              type: 'service_unavailable_error',
              param: null,
              code: 'server_is_overloaded',
            },
          },
        },
      },
    },
  },
}
